START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261023160002_AddClubPayouts') THEN
    CREATE TABLE "ClubPayoutAccounts" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "ClubId" integer NOT NULL,
        "Status" integer NOT NULL,
        "BusinessType" integer,
        "Region" integer NOT NULL,
        "Currency" character varying(3) NOT NULL,
        "LegalName" character varying(150),
        "TradingName" character varying(150),
        "AddressLine1" character varying(150),
        "AddressLine2" character varying(150),
        "City" character varying(100),
        "Postcode" character varying(12),
        "ContactEmail" character varying(200),
        "ContactPhone" character varying(30),
        "RegistrationNumber" character varying(20),
        "VatNumber" character varying(20),
        "PersonFullName" character varying(150),
        "PersonDateOfBirth" date,
        "StatementDescriptor" character varying(22),
        "Schedule" integer NOT NULL,
        "BankAccountHolder" character varying(150),
        "BankName" character varying(100),
        "SortCode" character varying(8),
        "AccountLast4" character varying(4),
        "IbanCountry" character varying(2),
        "IbanLast4" character varying(4),
        "CreatedAt" timestamp with time zone NOT NULL,
        "UpdatedAt" timestamp with time zone NOT NULL,
        "UpdatedByUserId" text,
        CONSTRAINT "PK_ClubPayoutAccounts" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_ClubPayoutAccounts_Clubs_ClubId" FOREIGN KEY ("ClubId") REFERENCES "Clubs" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261023160002_AddClubPayouts') THEN
    CREATE UNIQUE INDEX "IX_ClubPayoutAccounts_ClubId" ON "ClubPayoutAccounts" ("ClubId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261023160002_AddClubPayouts') THEN
    INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
    VALUES ('20261023160002_AddClubPayouts', '10.0.8');
    END IF;
END $EF$;
COMMIT;

